{
  "conversations": [
    {
      "title": "State my dietary restrictions",
      "lines": [
        { "speaker": "you", "text": "I'm vegan." },
        { "speaker": "partner", "text": "Vegan?" },
        { "speaker": "you", "text": "No meat, no fish, no dairy." },
        { "speaker": "you", "text": "No eggs, no honey, no dashi.", "or": true },
        { "speaker": "partner", "text": "Got it." }
      ]
    },
    {
      "title": "Ask about hidden ingredients",
      "lines": [
        { "speaker": "you", "text": "Does this have dashi in it?" },
        { "speaker": "partner", "text": "Yes, it does." },
        { "speaker": "partner", "text": "No, it doesn't.", "or": true },
        { "speaker": "you", "text": "Does this have egg in it?" },
        { "speaker": "partner", "text": "Just a little." },
        { "speaker": "partner", "text": "It's completely plant-based.", "or": true }
      ]
    },
    {
      "title": "Order vegan dishes",
      "lines": [
        { "speaker": "you", "text": "I'll take the vegetable plate, please." },
        { "speaker": "partner", "text": "Coming right up." },
        { "speaker": "you", "text": "I'll take the tofu salad, please.", "or": true },
        { "speaker": "partner", "text": "Anything else?" },
        { "speaker": "you", "text": "No, that's everything." },
        { "speaker": "you", "text": "Just some edamame too, please.", "or": true },
        { "speaker": "partner", "text": "Got it." }
      ]
    }
  ]
}
